import {redirect} from 'next/navigation';
import Link from 'next/link';
import {AppShell} from '@/components/AppShell';
import {createClient} from '@/lib/supabase/server';
import {createVendor} from '../actions';

const types=[['concrete_supplier','Concrete Supplier'],['pump','Concrete Pump'],['rebar_supplier','Rebar Supplier'],['building_materials','Building Materials'],['equipment_rental','Equipment Rental'],['trucking','Trucking / Hauling'],['traffic_control','Traffic Control'],['subcontractor','Subcontractor'],['other','Other']];
export default async function VendorsPage(){const supabase=await createClient();const {data:{user}}=await supabase.auth.getUser();if(!user)redirect('/login');const {data:p}=await supabase.from('profiles').select('full_name,company_id,role').eq('id',user.id).single();if(!p?.company_id)redirect('/login');if(p.role==='employee')redirect('/employee');const {data:vendors}=await supabase.from('vendors').select('*').eq('company_id',p.company_id).order('active',{ascending:false}).order('vendor_type').order('name');return <AppShell userName={p.full_name||user.email||'Owner'}><div className="contractor-page"><div className="command-hero"><div><h1>Vendors</h1><p>The companies Carez buys concrete, rebar, form material, rentals and subcontract work from.</p></div><div className="command-actions"><Link className="button secondary" href="/procurement">Back to Purchasing</Link></div></div><div className="command-grid"><div className="command-card"><div className="command-label">Active Vendors</div><div className="command-value">{(vendors||[]).filter((v:any)=>v.active).length}</div></div><div className="command-card"><div className="command-label">Concrete Suppliers</div><div className="command-value">{(vendors||[]).filter((v:any)=>v.vendor_type==='concrete_supplier').length}</div></div><div className="command-card"><div className="command-label">Rebar Suppliers</div><div className="command-value">{(vendors||[]).filter((v:any)=>v.vendor_type==='rebar_supplier').length}</div></div></div><section className="section"><div className="grid grid2"><div className="surface"><div className="surface-header"><div><div className="surface-title">Add Vendor</div><div className="surface-subtitle">Enter it once; use it for quotes, POs and bills.</div></div></div><div className="surface-body"><form action={createVendor} className="form"><div className="grid grid2"><label className="field"><span>Vendor Name</span><input name="name" required/></label><label className="field"><span>What Do They Supply?</span><select name="vendor_type">{types.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label></div><div className="grid grid2"><label className="field"><span>Contact</span><input name="contact_name"/></label><label className="field"><span>Phone</span><input name="phone"/></label></div><label className="field"><span>Email</span><input type="email" name="email"/></label><label className="field"><span>Address</span><input name="address_line1"/></label><div className="grid grid2"><label className="field"><span>City</span><input name="city"/></label><label className="field"><span>State</span><input name="state" defaultValue="WA"/></label></div><div className="grid grid2"><label className="field"><span>ZIP</span><input name="postal_code"/></label><label className="field"><span>Terms</span><input name="payment_terms" placeholder="Net 30, COD..."/></label></div><label className="field"><span>Account #</span><input name="account_number"/></label><label className="field"><span>Notes</span><input name="notes"/></label><button className="button">Save Vendor</button></form></div></div><div className="surface"><div className="surface-header"><div><div className="surface-title">Vendor Directory</div><div className="surface-subtitle">Quick contact list for the field and office.</div></div></div><div className="surface-body"><div className="list">{(vendors||[]).length===0?<div className="meta">No vendors yet.</div>:(vendors||[]).map((v:any)=><div className="row" key={v.id}><div><div className="title">{v.name}</div><div className="meta">{String(v.vendor_type).replaceAll('_',' ')} · {v.contact_name||'No contact'}</div><div className="meta">{v.phone||''}{v.phone&&v.email?' · ':''}{v.email||''}</div></div><span className={`status ${v.active?'active':''}`}>{v.active?'Active':'Inactive'}</span></div>)}</div></div></div></div></section></div></AppShell>}
